def fizzbuzz(n):
    def is_fizz(n):
        return n % 3 == 0
    def is_buzz(n):
        return n % 5 == 0

    result = []
    for i in range(1, n + 1):
        if is_fizz(i) and is_buzz(i):
            result.append("FizzBuzz")
        elif is_fizz(i):
            result.append("Fizz")
        elif is_buzz(i):
            result.append("Buzz")
        else:
            result.append(str(i))
    return result
```

